// The browser-level permission behind crawl consent. The store manifest keeps
// <all_urls> OPTIONAL so installing shows no "all your data on all websites"
// warning — access is requested at the moment the user consents (onboarding
// "Start learning" / settings toggle) and revoked when they withdraw it.
//
// Gesture rule (crbug.com/1284891): chrome.permissions.request() must be the
// FIRST call inside the click handler — user activation does not survive an
// earlier await. When the origins are already granted (or required, as in the
// dev build) request() resolves true without showing a prompt.
const CRAWL_ORIGINS = { origins: ['<all_urls>'] };

export function hasCrawlPermission(): Promise<boolean> {
  return chrome.permissions.contains(CRAWL_ORIGINS);
}

export function requestCrawlPermission(): Promise<boolean> {
  return chrome.permissions.request(CRAWL_ORIGINS).catch(() => false);
}

/** Revoke on consent withdrawal. A no-op when the permission is required
 * (dev build) — removing a required permission rejects, which we swallow. */
export function releaseCrawlPermission(): Promise<boolean> {
  return chrome.permissions.remove(CRAWL_ORIGINS).catch(() => false);
}

import { describe, expect, it } from 'vitest';
import {
  DEFAULT_WEIGHTS,
  lexicalScore,
  normalizeMagnitude,
  browseResults,
  folderPaths,
  rankQuality,
  rankResults,
  tokenize,
} from './search';
import { FETCH_STATUS, MATCH_REASON, type BookmarkRecord } from './types';

function rec(id: string, overrides: Partial<BookmarkRecord> = {}): BookmarkRecord {
  return {
    id,
    url: `https://example.com/${id}`,
    canonicalUrl: `https://example.com/${id}`,
    title: `Example ${id}`,
    folderPath: 'Bookmarks bar',
    dateAdded: 0,
    fetchStatus: FETCH_STATUS.Baseline,
    signals: {},
    compositeText: '',
    contentHash: '',
    tags: [],
    modelVersion: null,
    updatedAt: 0,
    ...overrides,
  };
}

describe('tokenize', () => {
  it('lowercases, splits on non-alphanumerics, dedupes, drops single chars', () => {
    expect(tokenize('GitHub — the/GitHub place! a')).toEqual(['github', 'the', 'place']);
  });
});

describe('lexicalScore', () => {
  it('scores a full phrase match in title at 1', () => {
    const r = rec('1', { title: 'AI Chat playground' });
    const { score, reason } = lexicalScore('ai chat', tokenize('ai chat'), r);
    expect(score).toBeGreaterThanOrEqual(1);
    expect(reason).toBe(MATCH_REASON.Title);
  });

  it('scores prefix token hits ("git" matches "github")', () => {
    const r = rec('1', { title: 'GitHub repos' });
    const { score } = lexicalScore('git', tokenize('git'), r);
    expect(score).toBeGreaterThan(0.6);
    expect(score).toBeLessThan(1);
  });

  it('uses tag reason when tags are the dominant evidence', () => {
    const r = rec('1', { title: 'Untitled', tags: ['ai-chat'] });
    const { reason } = lexicalScore('chat', tokenize('chat'), r);
    expect(reason).toBe(MATCH_REASON.Tag);
  });

  it('scores url tokens when title has no hits', () => {
    const r = rec('1', { title: 'Untitled', canonicalUrl: 'https://cursor.sh/features' });
    const { score, reason } = lexicalScore('cursor', tokenize('cursor'), r);
    expect(score).toBeGreaterThan(0.4);
    expect(reason).toBe(MATCH_REASON.Url);
  });

  it('gives folder matches the folder reason', () => {
    const r = rec('1', { title: 'Untitled', folderPath: 'Bookmarks bar / Recipes' });
    const { reason } = lexicalScore('recipes', tokenize('recipes'), r);
    expect(reason).toBe(MATCH_REASON.Folder);
  });

  it('scores crawled description/headings when no other field matches', () => {
    // merchants.to shape: marketing title, but the meta description names the topic.
    const r = rec('1', {
      title: 'Find The Best Deals On The Market',
      signals: {
        metaDescription: 'Compare prices and reviews in the Runescape gold market.',
        headings: ['Why use us?'],
      },
    });
    const { score, reason } = lexicalScore('gold prices', tokenize('gold prices'), r);
    expect(score).toBeGreaterThan(0.3);
    expect(reason).toBe(MATCH_REASON.Description);
  });

  it('keeps description evidence weaker than a title hit for the same query', () => {
    const titleHit = lexicalScore(
      'gold prices',
      tokenize('gold prices'),
      rec('1', { title: 'Gold prices today' }),
    );
    const descriptionHit = lexicalScore(
      'gold prices',
      tokenize('gold prices'),
      rec('2', { title: 'Untitled', signals: { metaDescription: 'Gold prices today' } }),
    );
    expect(descriptionHit.score).toBeGreaterThan(0);
    expect(descriptionHit.score).toBeLessThan(titleHit.score);
  });

  it('ignores the body excerpt for lexical scoring', () => {
    const r = rec('1', {
      title: 'Untitled',
      signals: { excerpt: 'gold prices appear only in the body text' },
    });
    const { score } = lexicalScore('gold prices', tokenize('gold prices'), r);
    expect(score).toBe(0);
  });
});

describe('rankQuality', () => {
  it('gives rank 1 the full signal and decays with rank', () => {
    expect(rankQuality(1, 15)).toBe(1);
    expect(rankQuality(3, 15)).toBeCloseTo(16 / 18, 5);
    expect(rankQuality(300, 15)).toBeLessThan(0.06);
  });

  it('sharpens the top-rank advantage as k shrinks', () => {
    const dropAtSmallK = rankQuality(1, 5) - rankQuality(10, 5);
    const dropAtLargeK = rankQuality(1, 60) - rankQuality(10, 60);
    expect(dropAtSmallK).toBeGreaterThan(dropAtLargeK);
  });
});

describe('normalizeMagnitude', () => {
  it('normalizes against the per-query max, clamped to [0,1]', () => {
    expect(normalizeMagnitude(0.7, 0.7, 0.5)).toBe(1); // this query's best
    expect(normalizeMagnitude(0.6, 0.7, 0.5)).toBeCloseTo(0.5, 5);
    expect(normalizeMagnitude(0.4, 0.7, 0.5)).toBe(0); // below floor
  });

  it('returns 0 when the whole distribution sits at/below the floor', () => {
    expect(normalizeMagnitude(0.45, 0.45, 0.5)).toBe(0);
  });
});

describe('rankResults', () => {
  it('returns [] for an empty or sub-token query', () => {
    expect(rankResults({ query: '', records: [rec('1')], semantic: [] })).toEqual([]);
    expect(rankResults({ query: 'a', records: [rec('1')], semantic: [] })).toEqual([]);
  });

  it('ranks exact-title matches above pure-semantic matches', () => {
    const records = [
      rec('semanticOnly', { title: 'Unrelated words entirely' }),
      rec('titleHit', { title: 'AI chat tools' }),
    ];
    const semantic = [{ id: 'semanticOnly', score: 0.9 }];
    const hits = rankResults({ query: 'ai chat', records, semantic });
    expect(hits[0]?.id).toBe('titleHit');
    expect(hits[1]?.id).toBe('semanticOnly');
    expect(hits[1]?.reason).toBe(MATCH_REASON.Semantic);
  });

  it('surfaces semantic-only hits that lexical would miss', () => {
    const records = [rec('warmr', { title: 'Warmr Documentation — warm up social posting' })];
    const semantic = [{ id: 'warmr', score: 0.82 }];
    const hits = rankResults({ query: 'warmup iphone ai', records, semantic });
    expect(hits).toHaveLength(1);
    expect(hits[0]?.id).toBe('warmr');
  });

  it('lifts a top-semantic-rank doc above bare single-token title matches', () => {
    // The merchants.to regression: marketing title, topic named only in the meta
    // description, semantic rank 3 — must beat docs whose only evidence is one
    // literal token in the title.
    const records = [
      rec('merchants', {
        title: 'Find The Best Deals On The Market',
        signals: {
          metaDescription:
            'Compare prices, reviews and payment methods in the Runescape gold market.',
        },
      }),
      ...Array.from({ length: 12 }, (_, i) => rec(`seller${i}`, { title: `Buy cheap gold ${i}` })),
    ];
    const semantic = [
      { id: 'seller0', score: 0.7 },
      { id: 'seller1', score: 0.69 },
      { id: 'merchants', score: 0.674 },
      { id: 'seller2', score: 0.66 },
    ];
    const hits = rankResults({ query: 'gold prices', records, semantic });
    const merchantsRank = hits.findIndex((h) => h.id === 'merchants');
    // Docs that beat it on BOTH channels (title hit + higher semantic rank) may
    // stay ahead; every bare title-token doc with no semantic evidence must not.
    expect(merchantsRank).toBeGreaterThanOrEqual(0);
    expect(merchantsRank).toBeLessThan(4);
    for (const [i, hit] of hits.entries()) {
      if (/^seller([3-9]|1[01])$/.test(hit.id)) expect(i).toBeGreaterThan(merchantsRank);
    }
  });

  it('gives no semantic credit when every cosine sits at/below the floor', () => {
    // "Best of the corpus" for a nonsense query is still irrelevant — rank alone
    // must not manufacture relevance.
    const records = [rec('noise', { title: 'Unrelated words entirely' })];
    const semantic = [{ id: 'noise', score: DEFAULT_WEIGHTS.semanticFloor }];
    expect(rankResults({ query: 'xyzzy plugh', records, semantic })).toEqual([]);
  });
});

describe('browseResults', () => {
  const library = [
    rec('old', { title: 'Alpha guide', dateAdded: 100 }),
    rec('new', { title: 'Zulu notes', dateAdded: 300 }),
    rec('mid', { title: 'Mango recipes', dateAdded: 200, folderPath: 'Bookmarks bar / Work' }),
    rec('deep', {
      title: 'Deep doc',
      dateAdded: 250,
      folderPath: 'Bookmarks bar / Work / Q3',
    }),
    rec('decoy', {
      title: 'Decoy',
      dateAdded: 150,
      // Name-prefix sibling: "Work" scope must NOT include "Workspace".
      folderPath: 'Bookmarks bar / Workspace',
    }),
  ];

  it('sorts newest-first by default', () => {
    const ids = browseResults({ records: library, sort: 'recent' }).map((h) => h.id);
    expect(ids).toEqual(['new', 'deep', 'mid', 'decoy', 'old']);
  });

  it('Recent is an activity timeline: opening an old bookmark bumps it to the top', () => {
    const lastOpened = new Map([
      ['old', 500], // opened after everything else was added — tops the list
      ['mid', 120], // opened before it was even re-added — the later dateAdded wins
    ]);
    const ids = browseResults({ records: library, sort: 'recent', lastOpened }).map((h) => h.id);
    expect(ids).toEqual(['old', 'new', 'deep', 'mid', 'decoy']);
  });

  it('name sort ignores activity (alphabetical is alphabetical)', () => {
    const lastOpened = new Map([['new', 999]]);
    const ids = browseResults({ records: library, sort: 'name', lastOpened }).map((h) => h.id);
    expect(ids).toEqual(['old', 'decoy', 'deep', 'mid', 'new']);
  });

  it('sorts by title when asked', () => {
    const ids = browseResults({ records: library, sort: 'name' }).map((h) => h.id);
    expect(ids).toEqual(['old', 'decoy', 'deep', 'mid', 'new']);
  });

  it('scopes a folder to itself and its subtree — never name-prefix siblings', () => {
    const ids = browseResults({
      records: library,
      sort: 'recent',
      folder: 'Bookmarks bar / Work',
    }).map((h) => h.id);
    expect(ids).toEqual(['deep', 'mid']);
  });

  it('marks dead-fetch records so the UI can show the quiet indicator', () => {
    const hits = browseResults({
      records: [
        rec('gone', { fetchStatus: FETCH_STATUS.Dead, dateAdded: 2 }),
        rec('fine', { dateAdded: 1 }),
      ],
      sort: 'recent',
    });
    expect(hits[0]?.dead).toBe(true);
    expect(hits[1]?.dead).toBeUndefined();
  });

  it('produces chip-less unranked hits with the row snippet fields intact', () => {
    const [hit] = browseResults({
      records: [rec('x', { signals: { metaDescription: 'A page about things.' } })],
      sort: 'recent',
    });
    expect(hit?.reason).toBe(MATCH_REASON.Title);
    expect(hit?.score).toBe(0);
    expect(hit?.description).toBe('A page about things.');
  });
});

describe('folderPaths', () => {
  it('dedupes and sorts, dropping empty paths', () => {
    const records = [
      rec('1', { folderPath: 'Other bookmarks' }),
      rec('2', { folderPath: 'Bookmarks bar' }),
      rec('3', { folderPath: 'Bookmarks bar' }),
      rec('4', { folderPath: '' }),
    ];
    expect(folderPaths(records)).toEqual(['Bookmarks bar', 'Other bookmarks']);
  });

  it('drops records below the minimum score', () => {
    const hits = rankResults({
      query: 'zzz qqq',
      records: [rec('1', { title: 'Nothing relevant' })],
      semantic: [],
    });
    expect(hits).toEqual([]);
  });

  it('respects the limit and sorts by score', () => {
    const records = Array.from({ length: 30 }, (_, i) =>
      rec(String(i), { title: `github item ${i}` }),
    );
    const hits = rankResults({ query: 'github', records, semantic: [], limit: 5 });
    expect(hits).toHaveLength(5);
    const scores = hits.map((h) => h.score);
    expect([...scores].sort((a, b) => b - a)).toEqual(scores);
  });
});

import 'fake-indexeddb/auto';
import { IDBFactory } from 'fake-indexeddb';
import { beforeEach, describe, expect, it } from 'vitest';
import * as storage from './storage';
import { FETCH_STATUS, type BookmarkRecord, type VectorRow } from './types';

function makeRecord(id: string, overrides: Partial<BookmarkRecord> = {}): BookmarkRecord {
  return {
    id,
    url: `https://example.com/${id}`,
    canonicalUrl: `https://example.com/${id}`,
    title: `Example ${id}`,
    folderPath: 'Bookmarks bar / Test',
    dateAdded: 1700000000000,
    fetchStatus: FETCH_STATUS.Pending,
    signals: {},
    compositeText: '',
    contentHash: '',
    tags: [],
    modelVersion: null,
    updatedAt: 1700000000000,
    ...overrides,
  };
}

beforeEach(() => {
  // Fresh database per test: reset the global factory and drop the cached connection.
  globalThis.indexedDB = new IDBFactory();
  storage.closeForTests();
});

describe('records store', () => {
  it('round-trips a record', async () => {
    const record = makeRecord('1', { tags: ['dev'] });
    await storage.putRecords([record]);
    expect(await storage.getRecord('1')).toEqual(record);
  });

  it('bulk-puts and getAll returns everything', async () => {
    await storage.putRecords([makeRecord('1'), makeRecord('2'), makeRecord('3')]);
    expect((await storage.getAllRecords()).map((r) => r.id).sort()).toEqual(['1', '2', '3']);
  });

  it('put with same id overwrites', async () => {
    await storage.putRecords([makeRecord('1', { title: 'old' })]);
    await storage.putRecords([makeRecord('1', { title: 'new' })]);
    expect((await storage.getRecord('1'))?.title).toBe('new');
    expect(await storage.getAllRecords()).toHaveLength(1);
  });

  it('deletes a record', async () => {
    await storage.putRecords([makeRecord('1')]);
    await storage.deleteRecord('1');
    expect(await storage.getRecord('1')).toBeUndefined();
  });
});

describe('vectors store', () => {
  it('round-trips Float32Array bytes intact', async () => {
    const vector = new Float32Array([0.1, -0.5, 0.25, 1]);
    const row: VectorRow = { id: '1', vector: vector.buffer, modelVersion: 'test@1' };
    await storage.putVectors([row]);
    const loaded = await storage.getVector('1');
    expect(loaded?.modelVersion).toBe('test@1');
    expect(Array.from(new Float32Array(loaded!.vector))).toEqual(Array.from(vector));
  });

  it('getAllVectors returns all rows', async () => {
    const buf = new Float32Array([1]).buffer;
    await storage.putVectors([
      { id: '1', vector: buf, modelVersion: 'test@1' },
      { id: '2', vector: buf, modelVersion: 'test@1' },
    ]);
    expect(await storage.getAllVectors()).toHaveLength(2);
  });

  it('deletes a vector', async () => {
    await storage.putVectors([
      { id: '1', vector: new Float32Array([1]).buffer, modelVersion: 'test@1' },
    ]);
    await storage.deleteVector('1');
    expect(await storage.getVector('1')).toBeUndefined();
  });
});

describe('meta store', () => {
  it('round-trips arbitrary values by key', async () => {
    await storage.setMeta('progress', { phase: 'fetching', processed: 10 });
    expect(await storage.getMeta('progress')).toEqual({ phase: 'fetching', processed: 10 });
  });

  it('returns undefined for missing keys', async () => {
    expect(await storage.getMeta('nope')).toBeUndefined();
  });

  it('deletes by key', async () => {
    await storage.setMeta('k', 1);
    await storage.deleteMeta('k');
    expect(await storage.getMeta('k')).toBeUndefined();
  });
});

describe('clearAll', () => {
  it('wipes every store', async () => {
    await storage.putRecords([makeRecord('1')]);
    await storage.putVectors([
      { id: '1', vector: new Float32Array([1]).buffer, modelVersion: 'v' },
    ]);
    await storage.setMeta('k', 'v');
    await storage.clearAll();
    expect(await storage.getAllRecords()).toHaveLength(0);
    expect(await storage.getAllVectors()).toHaveLength(0);
    expect(await storage.getMeta('k')).toBeUndefined();
  });
});

// Crawl/icon network work runs only with BOTH the user's stored consent and
// the live browser permission — either can disappear independently (prefs via
// settings, the permission via chrome://extensions site-access controls), so
// callers check this per use rather than caching.
import { getPrefs } from './prefs';
import { hasCrawlPermission } from '../lib/crawl-permission';

export async function hasCrawlConsent(): Promise<boolean> {
  if (!(await getPrefs()).crawlEnabled) return false;
  return hasCrawlPermission();
}

// Hybrid ranking (decision 003): instant lexical scoring fused with semantic
// cosine scores. Pure functions — no storage, no models — so ranking is fully
// unit-testable and tunable against the golden harness.
import {
  FETCH_STATUS,
  MATCH_REASON,
  type BookmarkRecord,
  type MatchReason,
  type ScoredHit,
} from './types';
import { tokenize } from '../lib/text';

export { tokenize };

export type RankWeights = {
  lexical: number;
  semantic: number;
  /** bge cosines cluster high; scores at/below the floor contribute nothing. */
  semanticFloor: number;
  /** RRF-style k — smaller sharpens the reward for the very top semantic ranks. */
  rankSharpness: number;
  /** Fraction of the semantic channel driven by corpus-relative rank; the rest
   * comes from per-query-normalized cosine magnitude (decision 007). */
  rankBlend: number;
};

// Tuned against tools/goldens.json — change via the harness, not by eye.
// lexical > semantic keeps exact-title hits above pure-vector hits (research:
// embeddings must not override literal-match intuition). The semantic channel
// is distribution-aware (decision 007): a fixed cosine ceiling can't see that
// e.g. 0.674 is the 3rd-best score of 1,346 for this query — rank can.
export const DEFAULT_WEIGHTS: RankWeights = {
  lexical: 0.55,
  semantic: 0.45,
  semanticFloor: 0.5,
  // k=5 from the tools/tune.mjs sweep (21/21 goldens, MRR 0.781): short
  // candidate lists want a small k so the very top ranks stand apart.
  rankSharpness: 5,
  rankBlend: 0.6,
};

/** Substring-phrase evidence only counts for multi-word queries — a single
 * short token as substring is noise ("git" would hit "Digital Trends"). */
const MIN_PHRASE_TOKENS = 2;
const MIN_PHRASE_LENGTH = 2;
/** Description cap: one scannable line at rest, ~3 clamped lines in the
 * hover-expanded detail card (the card clips the rest via CSS). */
const SNIPPET_MAX_CHARS = 240;
const PHRASE_SCORE = 1;
const TITLE_COVERAGE_SCORE = 0.9;
const TAG_COVERAGE_SCORE = 0.65;
const URL_COVERAGE_SCORE = 0.55;
const FOLDER_COVERAGE_SCORE = 0.4;
/** Crawled description/headings/site-name: author-written page summaries, so real
 * literal evidence — but the weakest field, so page marketing copy can never outshout
 * a title/tag/url hit. The body excerpt is deliberately excluded from lexical scoring
 * (too noisy); meaning-level body matches are the semantic channel's job. */
const DESCRIPTION_COVERAGE_SCORE = 0.35;
/** A prefix hit ("git" → "github") is worth most of an exact token hit. */
const PREFIX_HIT_VALUE = 0.8;
/** Small boost when several independent components agree. */
const MULTI_COMPONENT_BONUS = 0.05;
/** Lexical evidence below this is too weak to be the honest "reason". */
const LEXICAL_REASON_THRESHOLD = 0.45;
/** Floor below which a hit carries no real evidence at all. Kept low: the popup
 * renders progressively (infinite scroll), so a browsable evidence-bearing tail
 * beats a hard cliff — ordering still puts the best first. */
const MIN_RESULT_SCORE = 0.05;
/** Max hits returned per search. The popup renders these in chunks as the user
 * scrolls; ranking 1–5k records takes a few ms, so depth is effectively free.
 * Exported so the footer counter can say "Top N" instead of a false total. */
export const SEARCH_LIMIT = 150;

/** 1 for an exact token hit, PREFIX_HIT_VALUE for a prefix hit, else 0. */
function tokenHit(queryToken: string, target: ReadonlySet<string>): number {
  if (target.has(queryToken)) return 1;
  for (const token of target) {
    if (token.startsWith(queryToken)) return PREFIX_HIT_VALUE;
  }
  return 0;
}

/** Fraction of query tokens found in target tokens (exact or prefix). */
function coverage(queryTokens: readonly string[], targetTokens: readonly Set<string>[]): number {
  if (!queryTokens.length) return 0;
  let sum = 0;
  for (const qt of queryTokens) {
    let best = 0;
    for (const target of targetTokens) {
      best = Math.max(best, tokenHit(qt, target));
      if (best === 1) break;
    }
    sum += best;
  }
  return sum / queryTokens.length;
}

export type LexicalScore = { score: number; reason: MatchReason };

export function lexicalScore(
  query: string,
  queryTokens: readonly string[],
  record: BookmarkRecord,
): LexicalScore {
  const title = record.title.toLowerCase();
  const components: { score: number; reason: MatchReason }[] = [];

  const phrase = query.trim().toLowerCase();
  if (
    queryTokens.length >= MIN_PHRASE_TOKENS &&
    phrase.length >= MIN_PHRASE_LENGTH &&
    title.includes(phrase)
  ) {
    components.push({ score: PHRASE_SCORE, reason: MATCH_REASON.Title });
  }

  const titleTokens = new Set(tokenize(record.title));
  components.push({
    score: coverage(queryTokens, [titleTokens]) * TITLE_COVERAGE_SCORE,
    reason: MATCH_REASON.Title,
  });

  // Learned (cluster-discovered) topics count as tags too — they're the
  // user's own vocabulary, often exactly what they'll type.
  const tagTokens = new Set(
    [...record.tags, ...(record.learnedTags ?? [])].flatMap((t) => tokenize(t)),
  );
  components.push({
    score: coverage(queryTokens, [tagTokens]) * TAG_COVERAGE_SCORE,
    reason: MATCH_REASON.Tag,
  });

  const urlTokens = new Set(tokenize(record.canonicalUrl || record.url));
  components.push({
    score: coverage(queryTokens, [urlTokens]) * URL_COVERAGE_SCORE,
    reason: MATCH_REASON.Url,
  });

  const folderTokens = new Set(tokenize(record.folderPath));
  components.push({
    score: coverage(queryTokens, [folderTokens]) * FOLDER_COVERAGE_SCORE,
    reason: MATCH_REASON.Folder,
  });

  const descriptionTokens = new Set([
    ...tokenize(record.signals.metaDescription ?? ''),
    ...tokenize(record.signals.siteName ?? ''),
    ...(record.signals.headings ?? []).flatMap((h) => tokenize(h)),
  ]);
  components.push({
    score: coverage(queryTokens, [descriptionTokens]) * DESCRIPTION_COVERAGE_SCORE,
    reason: MATCH_REASON.Description,
  });

  let best: { score: number; reason: MatchReason } = { score: 0, reason: MATCH_REASON.Title };
  let hits = 0;
  for (const c of components) {
    if (c.score <= 0) continue;
    hits++;
    if (c.score > best.score) best = c;
  }
  const bonus = hits > 1 ? (hits - 1) * MULTI_COMPONENT_BONUS : 0;
  return { score: Math.min(1, best.score + bonus), reason: best.reason };
}

/** One entry of the semantic ranking: a record id and its raw cosine. */
export type SemanticNeighbor = { id: string; score: number };

/** Corpus-relative rank quality: 1 at rank 1, decaying like weighted RRF.
 * (k+1)/(k+rank) instead of 1/(k+rank) keeps the signal on a [0,1] scale so
 * channel weights stay comparable (research: Qdrant's scale warning). */
export function rankQuality(rank: number, sharpness: number): number {
  return (sharpness + 1) / (sharpness + rank);
}

/** Cosine magnitude normalized against THIS query's best cosine (per-query
 * max, not a fixed ceiling — Bruch et al.'s TM2C2 normalization). */
export function normalizeMagnitude(cosine: number, maxCosine: number, floor: number): number {
  const span = maxCosine - floor;
  if (span <= 0) return 0;
  return Math.min(1, Math.max(0, (cosine - floor) / span));
}

/** Sorted rank lookup (1-based, cosine descending) built defensively so callers
 * need not guarantee input order. Sub-ms at ≤5k entries. */
function semanticRanks(semantic: readonly SemanticNeighbor[]): Map<string, number> {
  const sorted = [...semantic].sort((a, b) => b.score - a.score);
  return new Map(sorted.map((entry, i) => [entry.id, i + 1]));
}

function toHit(record: BookmarkRecord, score: number, reason: MatchReason): ScoredHit {
  const description = record.signals.metaDescription ?? record.signals.excerpt;
  return {
    id: record.id,
    title: record.title,
    url: record.url,
    score,
    reason,
    // Taxonomy tags first, learned topics after — the card's chip cap trims
    // from the tail, so curated tags keep priority.
    tags: record.learnedTags?.length ? [...record.tags, ...record.learnedTags] : record.tags,
    folderPath: record.folderPath,
    dateAdded: record.dateAdded,
    ...(description ? { description: description.slice(0, SNIPPET_MAX_CHARS) } : {}),
    ...(record.fetchStatus === FETCH_STATUS.Dead ? { dead: true } : {}),
  };
}

export type BrowseSort = 'recent' | 'name';

/** Folder-path separator as ingest writes it ("Other bookmarks / Work"). */
const FOLDER_SEP = ' / ';

/** Browse-at-rest: the whole library as hits — no query, no scoring. Reason
 * Title renders chip-less and score 0 is honest ("listed, not ranked"). */
export function browseResults(args: {
  records: readonly BookmarkRecord[];
  sort: BrowseSort;
  /** Full folderPath — scopes to that folder AND its subtree. */
  folder?: string;
  /** recordId → last time the user OPENED it through the extension. "Recent"
   * is a unified activity timeline: the later of added and last opened —
   * opening a bookmark bumps it to the top, exactly like a recents list. */
  lastOpened?: ReadonlyMap<string, number>;
}): ScoredHit[] {
  const { records, sort, folder, lastOpened } = args;
  const scoped = folder
    ? records.filter((r) => r.folderPath === folder || r.folderPath.startsWith(folder + FOLDER_SEP))
    : [...records];
  const activity = (r: BookmarkRecord): number => Math.max(r.dateAdded, lastOpened?.get(r.id) ?? 0);
  scoped.sort(
    sort === 'name'
      ? (a, b) => a.title.localeCompare(b.title) || b.dateAdded - a.dateAdded
      : (a, b) => activity(b) - activity(a) || a.title.localeCompare(b.title),
  );
  return scoped.map((record) => toHit(record, 0, MATCH_REASON.Title));
}

/** Unique folder paths for the browse filter, alphabetical. */
export function folderPaths(records: readonly BookmarkRecord[]): string[] {
  return [...new Set(records.map((r) => r.folderPath).filter(Boolean))].sort((a, b) =>
    a.localeCompare(b),
  );
}

export function rankResults(args: {
  query: string;
  records: readonly BookmarkRecord[];
  /** Full semantic ranking — every embedded record with its raw cosine (may be empty). */
  semantic: readonly SemanticNeighbor[];
  weights?: RankWeights;
  limit?: number;
}): ScoredHit[] {
  const { query, records, semantic } = args;
  const weights = args.weights ?? DEFAULT_WEIGHTS;
  const limit = args.limit ?? SEARCH_LIMIT;

  const queryTokens = tokenize(query);
  if (!queryTokens.length) return [];

  const cosineById = new Map(semantic.map((entry) => [entry.id, entry.score]));
  const rankById = semanticRanks(semantic);
  const maxCosine = semantic.length ? Math.max(...semantic.map((entry) => entry.score)) : 0;

  const hits: ScoredHit[] = [];
  for (const record of records) {
    const lex = lexicalScore(query, queryTokens, record);
    const rank = rankById.get(record.id);
    const cosine = cosineById.get(record.id) ?? 0;
    // The absolute floor gates the WHOLE semantic channel: being "rank 1 of the
    // corpus" for a query nothing actually matches must not manufacture relevance.
    const sem =
      rank === undefined || cosine <= weights.semanticFloor
        ? 0
        : weights.rankBlend * rankQuality(rank, weights.rankSharpness) +
          (1 - weights.rankBlend) * normalizeMagnitude(cosine, maxCosine, weights.semanticFloor);
    const score = weights.lexical * lex.score + weights.semantic * sem;
    if (score < MIN_RESULT_SCORE) continue;

    const reason: MatchReason =
      lex.score >= LEXICAL_REASON_THRESHOLD && weights.lexical * lex.score >= weights.semantic * sem
        ? lex.reason
        : MATCH_REASON.Semantic;

    hits.push(toHit(record, score, reason));
  }

  hits.sort((a, b) => b.score - a.score || a.title.localeCompare(b.title));
  return hits.slice(0, limit);
}
